            return a.Kind == 3 && b.Kind == 3 ? Percentage(subtract ? a.Number - b.Number : a.Number + b.Number) : Nothing;
        }

        internal static Value Multiply(Value a, Value b, bool product, bool leftPercentage, bool rightPercentage)
        {
